sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?place ?country WHERE {
  VALUES ?place { dbr:Selo_sanatoriya_imeni_Chekhova dbr:Volovo,_Lipetsk_Oblast }
  OPTIONAL { ?place dbp:country ?c1 . }
  OPTIONAL { ?place dbo:country ?c2 . }
  BIND (COALESCE(?c1, ?c2) AS ?country)
}
LIMIT 100

